**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

bool czyPierwsza(int c) {
    return c == 2 || c == 3 || c == 5 || c == 7;
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        string s = to_string(liczba);
        int utworzona = 0;
        bool maCP = false;
        for (char ch : s) {
            int c = ch - '0';
            if (czyPierwsza(c)) {
                utworzona = utworzona * 10 + c;
                maCP = true;
            }
        }
        cout << liczba << ": ";
        if (!maCP) {
            cout << "brak cyfr pierwszych" << endl;
        } else {
            int reszta = liczba % utworzona;
            cout << "cyfry pierwsze -> " << utworzona << ", "
                 << liczba << " % " << utworzona << " = " << reszta;
            if (reszta == 0) {
                cout << " -> TAK" << endl;
                ile++;
            } else {
                cout << " -> NIE" << endl;
            }
        }
    }
    cout << "Liczb podzielnych przez liczbe z cyfr pierwszych: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Przechodzimy cyfry od lewej do prawej (jako string). Jesli cyfra jest pierwsza (2,3,5,7), dolaczamy ja do budowanej liczby (`utworzona = utworzona*10 + cyfra`). Na koncu sprawdzamy podzielnosc. Jesli nie ma zadnych cyfr pierwszych, wypisujemy komunikat.

